// Guided lessons transfer a specific skill into work; the full learning activities
// keep their independent prompts, examples and acceptance checks.
const guidedPairs: Record<number, number> = { 1:1, 2:4, 3:4, 4:9, 5:16, 6:3, 7:14, 8:16, 9:11, 10:8, 11:10, 12:19, 13:13, 14:6, 15:7, 16:4, 17:20, 18:22, 19:21, 20:21, 21:5, 22:23, 23:18, 24:24 };
