guidedWork[1] = { ...businessWork[1], when: 'You want to clarify a real request before asking AI to produce the work.', prompt: 'Help me clarify this task before doing it. Using only the supplied request, list confirmed facts, possible assumptions and the three questions whose answers would most change the output. Explain why each question matters. Write a clearer request using confirmed facts and explicit questions. Do not produce the requested work yet.', output: 'A clearer request and three important clarification questions.' };
guidedWork[2] = { ...businessWork[4], when: 'You need to understand the current position in a long email thread.', prompt: 'Read this thread before drafting a reply. Build a dated timeline of proposals and agreements. Identify the latest confirmed position, superseded dates, conditions and unanswered questions. Quote evidence for current commitments. Finish with a two-sentence summary and points I should verify. Do not draft a reply yet.', output: 'A checked current-position summary and timeline.', template: 'Date\tProposal or agreement\tEvidence\tCurrent / superseded\n[ ]\t[ ]\t[ ]\t[ ]\nCurrent position:\nOpen questions:' };
guidedWork[3] = { ...businessWork[4], when: 'The same message needs to work for different audiences.', inputs: ['Approved message', 'Audience and action needed', 'Facts that must remain unchanged'], prompt: 'Adapt this approved message for [audience] in [tone] under [word limit] words. First list the facts that must survive: dates, required actions, conditions and help contact. Return the rewritten message and a factual comparison checklist. Explain any unfamiliar term. Do not add a promise, policy rule or quantified benefit.', output: 'An audience-appropriate message and a factual comparison checklist.', variantIds: ['communications-change', 'hr-enquiry'] };
guidedWork[5] = { ...businessWork[16], app: apps.Docs[0], appUrl: apps.Docs[1], when: 'An AI draft sounds convincing and needs evidence checking.', inputs: ['The draft', 'Original source documents'], prompt: 'Audit this draft against the supplied sources. For each factual claim show the claim, exact evidence and one label: supported, contradicted or not established. Distinguish lack of evidence from proof of error. Return a corrected draft without new claims and three checks for me to perform against the originals.', output: 'A claim-by-claim audit and a corrected draft.', template: 'Claim\tEvidence\tSupported / contradicted / not established\tCorrection\n[ ]\t[ ]\t[ ]\t[ ]' };
guidedWork[7] = { ...businessWork[14], when: 'An expert has rough notes that need to become a usable procedure.', inputs: ['Permitted expert notes', 'Intended user and task', 'Known process owner'], prompt: 'Turn these expert notes into a draft procedure for [audience]. Include purpose, inputs, ordered steps, checks, exceptions and open questions. Preserve the supplied counting or decision rules. Do not invent sign-off, storage locations or missing process steps. Mark unresolved details and give questions for the process owner.', output: 'An expert-review procedure draft with visible gaps.', template: 'Purpose:\nAudience:\nInputs:\nStep\tAction\tCheck\tSource / unresolved question\n1\t[ ]\t[ ]\t[ ]\nExceptions:\nOwner review:', variantIds: ['hr-onboarding', 'reporting-quality'] };
guidedWork[8] = { ...businessWork[16], when: 'You need to understand what changed between document versions.', inputs: ['Old and new approved documents', 'Version and effective dates', 'Date the answer must apply to'], prompt: 'Compare these two document versions. Return topic, old requirement, new requirement, supporting passage and practical impact. Distinguish wording changes from changed requirements. State which version applies on [date]. Treat silence in an old source as unspecified, not proof of an old exemption. List questions for the owner.', output: 'A source-linked change-impact table.', template: 'Topic\tOld requirement\tNew requirement\tEvidence\tPractical impact\n[ ]\t[ ]\t[ ]\t[ ]\t[ ]', variantIds: ['hr-enquiry', 'procurement-renewal'] };
guidedWork[10] = { ...businessWork[8], prompt: 'Before analyzing [table or range], describe what one row represents and what is required to count records or total values correctly. Inspect identifiers, duplicates, date formats, missing categories and unusual numbers. Show row references and the reporting implications. Do not clean, chart or calculate totals until unresolved issues are explained.', output: 'A data-readiness note explaining what can and cannot be concluded.' };
guidedWork[11] = { ...businessWork[10], prompt: 'Using [table or range] and [definitions], show the calculation behind each reported change. Explain whether rates must be weighted by a denominator. Distinguish relative percent change and percentage-point change. Return one factual headline, three observations and two unanswered why-questions. Do not invent a cause.', output: 'A checked headline and an explanation of the calculation behind it.' };
guidedWork[16] = { ...businessWork[4], app: apps.Docs[0], appUrl: apps.Docs[1], when: 'A business change needs consistent communication across audiences.', inputs: ['Approved announcement', 'Audience groups', 'Confirmed required action and date'], prompt: 'Adapt this approved announcement into an employee email under 120 words, four manager talking points and a five-question FAQ. First build a shared factual checklist. Preserve dates, required actions, exceptions and authorization rules. Keep unanswered questions visible. Do not add benefits, promises or policy details absent from the source.', output: 'A consistent employee email, manager brief and FAQ.', tasks: ['email', 'presentation'], variantIds: ['communications-change', 'hr-enquiry'] };
guidedWork[20] = { ...businessWork[21], when: 'You need to test whether saved instructions work on difficult inputs.', inputs: ['Saved instructions', 'Current source document', 'Complete, missing, outside-scope and conflicting test cases'], prompt: 'Create an evaluation table for these reusable instructions: case, input sources, expected behaviour, actual result, pass/fail and revision needed. Include complete, missing, outside-scope and contradictory-source cases. Leave actual results blank until I run each case. After one revision, propose which previously passing case I should retest.', output: 'A small test log with observable success criteria.', template: 'Case\tSources\tExpected behaviour\tActual result\tPass / fail\tRevision\nComplete\t[ ]\t[ ]\t\t\t\nMissing input\t[ ]\t[ ]\t\t\t\nOutside scope\t[ ]\t[ ]\t\t\t\nContradictory source\t[ ]\t[ ]\t\t\t', quickMinutes:15 };
guidedWork[23] = { ...businessWork[18], app: apps.Docs[0], appUrl: apps.Docs[1], when: 'Another colleague must be able to continue your work during an absence.', inputs: ['Current work notes', 'Confirmed deadlines and dependencies', 'Coverage, authority and source locations'], prompt: 'Create a practical handover from these notes. Include current work, confirmed and proposed dates, dependencies, coverage, decision authority, source locations and unresolved gaps. Mark missing links as not supplied. Do not turn coverage into approval authority. Add five questions the covering colleague should be able to answer.', output: 'A handover that a covering colleague can check and use.', template: 'Work item\tStatus\tNext action\tConfirmed deadline\tDependency\tCover / authority\tSource location\tGap\n[ ]\t[ ]\t[ ]\t[ ]\t[ ]\t[ ]\t[ ]\t[ ]', tasks:['actions', 'documents'], variantIds: ['operations-handover'], level:'Starter' };
guidedWork[2].steps = ['Open the relevant thread in Gmail and Ask Gemini.', 'Generate the timeline and current-position summary before requesting a reply.', 'Read the quoted messages and check which proposals are superseded.'];
guidedWork[2].checks = ['Current dates come from the latest agreement.', 'Every quotation matches the original message.', 'A question or proposal has not become a commitment.'];
guidedWork[3].steps = ['Open the approved message in Gmail or Docs and identify the intended audience.', 'Set the audience, tone and word limit in the work prompt.', 'Compare the rewrite with the original factual checklist before using it.'];
guidedWork[3].template = 'Audience / action needed:\nFacts to preserve:\nRewritten message:\nFact-by-fact comparison:\nQuestions still unanswered:';
guidedWork[5].steps = ['Open the original sources and AI draft in your approved Docs/Gemini experience.', 'Generate a claim-by-claim audit and inspect the evidence for each label.', 'Correct the draft and personally verify the most important claims against the originals.'];
guidedWork[5].checks = ['Read the evidence behind each label.', 'No evidence is distinguished from proven false.', 'The corrected draft adds no unsupported claims.'];
guidedWork[7].steps = ['Open the permitted expert notes in Docs and identify the intended user.', 'Generate the draft procedure with unresolved steps visibly marked.', 'Walk through one example with the process owner and resolve or retain the gaps.'];
guidedWork[7].checks = ['The original rules and counting definitions are preserved.', 'Missing decisions are visibly unresolved.', 'A process owner reviews the draft before it is adopted.'];
guidedWork[8].steps = ['Add both versions as clearly named sources with effective dates.', 'Generate the change-impact table for the date you need.', 'Open the supporting passages and confirm which instructions apply.'];
guidedWork[8].checks = ['Requirements and wording changes are distinguished.', 'The applicable version follows the effective date.', 'Silence in an old source is not treated as an exemption.'];
guidedWork[10].steps = ['Preserve a source tab and identify the table grain and unique key.', 'Generate a data-readiness report before totals, cleaning or charts.', 'Inspect flagged rows and record which reporting questions remain answerable.'];
guidedWork[11].steps = ['Select the relevant table and supply its metric definitions.', 'Calculate the rates and independently check a denominator and one change.', 'Review the headline, observations and unanswered questions for correct units and evidence.'];
guidedWork[16].steps = ['Open the approved announcement in Docs and list the facts all formats must preserve.', 'Generate the employee email, manager talking points and FAQ.', 'Compare every format with the source and ask a colleague to identify the required action.'];
guidedWork[16].template = 'Shared factual checklist:\nEmployee email:\nManager talking points:\nFAQ question\tSource-backed answer\tUnresolved detail\n[ ]\t[ ]\t[ ]';
guidedWork[20].steps = ['Open the saved instructions and a blank test log; identify the version being tested.', 'Define expected behaviour, then actually run complete, missing, outside-scope and contradictory cases.', 'Record actual results, revise one instruction, and rerun failed and previously passing cases.'];
guidedWork[20].checks = ['Actual results come from observed runs.', 'Pass/fail criteria are written before evaluating.', 'A revised version is retested on a previously passing case.'];
guidedWork[23].steps = ['Open your current work notes in Docs and distinguish confirmed details from proposals.', 'Generate the handover, source locations and questions for the covering colleague.', 'Ask the covering colleague to walk through it and resolve or explicitly retain the gaps.'];
guidedWork[23].checks = ['Confirmed and proposed dates are distinct.', 'Coverage does not imply approval authority.', 'Missing source links remain visible questions.'];

const businessPairs: Record<number, number> = { 1:1, 2:2, 3:6, 4:3, 5:21, 6:14, 7:15, 8:10, 9:4, 10:11, 11:9, 12:17, 13:13, 14:7, 15:15, 16:8, 17:20, 18:23, 19:12, 20:17, 21:19, 22:18, 23:22, 24:24 };
export const workFor = (track: TrackId, day: number) => (track === 'business' ? businessWork : guidedWork)[day];
export const relatedFor = (track: TrackId, day: number) => ({ track: track === 'business' ? 'guided' as const : 'business' as const, day: (track === 'business' ? businessPairs : guidedPairs)[day] });

const variantGuides: Record<string, WorkGuide> = {
  'finance-query': { ...businessWork[4], output:'A checked invoice-query reply and missing-information list.', steps:['Open the invoice query and permitted record in your approved Gemini experience.', 'Generate the source-based reply using the department prompt.', 'Check the reference, amount and status; send only after your normal review.'] },
  'finance-commentary': businessWork[10],
  'hr-enquiry': businessWork[13],
  'hr-onboarding': businessWork[14],
  'recruitment-intake': businessWork[1],
  'supplier-email': { ...businessWork[4], output:'A concise supplier email requesting comparable information.', steps:['Open the supplier correspondence and proposal in your approved Gemini experience.', 'Generate numbered clarification questions against the required scope.', 'Verify known prices and missing terms before sending the draft yourself.'] },
  'procurement-renewal': { ...businessWork[16], app:apps.Docs[0], appUrl:apps.Docs[1], output:'A source-linked renewal checklist and owner questions.', steps:['Open the permitted agreement and supplier correspondence in your approved Gemini experience.', 'Generate a checklist separating confirmed, proposed and unknown terms.', 'Read the evidence and take unresolved terms to the contract owner.'] },
  'operations-handover': guidedWork[23],
  'operations-routing': { ...businessWork[5], output:'A tested personal status-notification flow.', steps:['Create a flow with a unique training-status subject marker.', 'Map the starter variables to work item, status, owner and checkpoint; notify only yourself.', 'Test complete, missing and unrelated cases, inspect run history, then turn off the training flow.'] },
  'reporting-quality': { ...businessWork[10], output:'A checked metric formula and independent calculation.', steps:['Identify the source range, metric definition and existing formula.', 'Generate the formula review with numerator, denominator and cell references.', 'Reproduce one calculation independently and apply only confirmed corrections in a working copy.'] },
  'communications-change': { ...guidedWork[16], output:'A consistent employee email, manager brief and short storyboard.' },
  'leader-decision': { ...businessWork[12], output:'A short evidence-based decision brief.', steps:['Open a brief Doc with the checked evidence and proposed options.', 'Generate the decision brief with unknowns and proposals visible.', 'Check each claim and take the questions to the decision owner.'] },
};
export const departmentVariants: Record<string, DepartmentVariant> = Object.fromEntries(([
  { id:'finance-query', department:'Finance', title:'Resolve an invoice query', inputs:['Invoice query and permitted invoice record', 'Current review or escalation rules'], prompt:'Using the supplied invoice query and records, draft a response with confirmed invoice facts, missing information and next action. Distinguish a payment-status question from payment authorization. Do not promise a payment date. Keep amounts and references exact and cite the source field.', example:'TRAINING EXAMPLE. Supplier Cedar asks when INV-507 for EUR 1,240 will be paid. The record shows received 8 December 2026, PO-81, status Pending receipt confirmation. No payment date is recorded. The buyer must confirm receipt before Finance can continue the review.', template:'Invoice reference:\nConfirmed amount / status:\nMissing confirmation:\nQuestion for buyer:\nDraft supplier reply:', checks:['Reference and amount match.', 'No payment date or approval is invented.'] },
  { id:'finance-commentary', department:'Finance', title:'Explain a month-end variance', inputs:['Checked actual and budget figures', 'Period and metric definition', 'Known explanations with evidence'], prompt:'Write month-end commentary using these checked figures. Show actual minus budget and the relative change with the budget denominator. State the accounting sign convention before calling the result favourable or adverse. Separate known facts, possible explanations and questions. Do not invent drivers or forecasts.', example:'TRAINING EXAMPLE. November external-service expense: actual EUR 52,000, budget EUR 48,000. Positive actual-minus-budget means expense above budget. Three invoices totalling EUR 3,000 relate to a previously planned service; their budget treatment has not been confirmed. No other causal evidence is supplied.', template:'Metric / period:\nActual:\nBudget:\nVariance and calculation:\nConfirmed facts:\nUnresolved explanation:\nQuestion for owner:', checks:['Use the budget as the relative-change denominator.', 'An observed invoice does not by itself prove the full cause.'] },
  { id:'hr-enquiry', department:'HR', title:'Answer an employee learning enquiry', inputs:['Employee question', 'Current approved guidance and scope'], prompt:'Draft a helpful response to this employee question using only the supplied guidance. Show the applicable rule, missing information, next step and source passage. Keep unknown eligibility or approval unresolved. Do not invent benefits, policy exceptions or approval authority.', example:'TRAINING EXAMPLE, NOT COMPANY POLICY. A learning request includes course name, job relevance and estimated cost. The employee submits it to their manager for review. The guidance does not specify a budget limit or approval turnaround. An employee asks whether a EUR 600 course will automatically be approved by Friday.', template:'Question:\nApplicable guidance:\nWhat is confirmed:\nWhat is not specified:\nNext step:\nDraft response:', checks:['No budget threshold or approval date is invented.', 'Submitting a request is not described as approval.'] },
  { id:'hr-onboarding', department:'HR', title:'Prepare a new-starter checklist', inputs:['Role outcomes', 'Approved first-week learning materials', 'Confirmed access and buddy details'], prompt:'Create a first-week checklist from these notes, with task, purpose, prerequisite, source and owner to confirm. Separate learning activities from live-system access. Leave missing names, meeting times and permissions as questions. Add a short buddy walkthrough.', example:'TRAINING EXAMPLE. A new reporting coordinator should read the metric glossary, practise checking the sample report, observe a report review and explain one calculation to a buddy. Access to the reporting folder requires approval. No buddy name, meeting time or access decision is supplied.', template:'Task\tPurpose\tPrerequisite\tSource\tOwner to confirm\n[ ]\t[ ]\t[ ]\t[ ]\t[ ]', checks:['Access is not assumed.', 'Learning tasks have a clear outcome and source.'] },
  { id:'recruitment-intake', department:'Recruitment', title:'Clarify a hiring-manager intake', inputs:['Approved role request', 'Confirmed outcomes and competencies', 'Known hiring constraints'], prompt:'Turn this role request into a hiring-manager intake brief with outcomes, competencies, confirmed requirements and clarification questions. Draft job-related interview topics with blank evidence fields. Do not add qualifications, score candidates or infer personal characteristics.', example:'TRAINING EXAMPLE. A hiring manager requests a Service Reporting Coordinator to maintain a KPI glossary, prepare checked weekly reports and explain data issues to stakeholders. Competencies: spreadsheet analysis, problem solving and clear communication. Start date and reporting line are unconfirmed. No degree or experience threshold is supplied.', template:'Role outcomes:\nRequired competencies:\nConfirmed requirements:\nIntake questions:\nInterview topic\tRequirement\tEvidence notes\n[ ]\t[ ]\t', checks:['Requirements come from the role request.', 'Unspecified criteria remain questions.'] },
  { id:'supplier-email', department:'Procurement', title:'Ask a supplier for comparable information', inputs:['Proposal and required scope', 'Unresolved commercial details'], prompt:'Draft a supplier clarification email using the proposal and requirements. Ask numbered questions needed for a like-for-like comparison. Preserve known prices and distinguish missing information from non-compliance. Do not negotiate commitments or select a supplier.', example:'TRAINING EXAMPLE. Birch offers 40 users for EUR 10,000 annually plus EUR 4,000 setup. The requirement is 50 users, export capability and weekday support. Export and weekday support are confirmed; pricing for ten additional users and renewal uplift are not supplied.', template:'Subject:\nConfirmed scope:\nQuestion 1 - additional users:\nQuestion 2 - renewal terms:\nOther unresolved requirements:\nDraft email:', checks:['Known costs are preserved.', 'Missing commercial terms are questions.'] },
  { id:'procurement-renewal', department:'Procurement', title:'Prepare a renewal review', inputs:['Current agreement and amendment', 'Renewal date and required decision', 'Permitted supplier evidence'], prompt:'Build a renewal checklist from these sources: current scope, renewal date, notice period, price evidence, unresolved terms and decision needed. Cite every contractual fact. Do not infer absent termination rights, legal conclusions or price commitments. List questions for the contract owner.', example:'TRAINING EXAMPLE. The current subscription ends 31 March 2027. The supplied summary says 50 included users and weekday support. A supplier email proposes a 5% uplift, subject to a new order. The notice clause and contract-owner identity are not included. No renewal has been approved.', template:'Term\tEvidence\tConfirmed / proposed / unknown\tQuestion for owner\n[ ]\t[ ]\t[ ]\t[ ]', checks:['Proposed pricing is not treated as agreed.', 'Absent clauses are not invented.'] },
  { id:'operations-handover', department:'Operations', title:'Hand over a service queue', inputs:['Current queue notes', 'Confirmed deadlines and coverage', 'Escalation roles'], prompt:'Create a queue handover with work item, status, next action, confirmed deadline, dependency, coverage and escalation. Separate proposed arrangements from agreed ones. Do not invent a ticket link, assign approval authority or silently reprioritise the queue.', example:'TRAINING EXAMPLE. Queue snapshot at 15:00: ticket T-81 awaits a supplier response; follow-up is due tomorrow at noon. T-82 has complete information and awaits service-owner review; no completion date agreed. Sam covers incoming queries tomorrow; change-approval authority has not been assigned. Ticket links are not supplied.', template:'Item\tStatus\tNext action\tDeadline\tDependency\tCover\tEscalation / gap\n[ ]\t[ ]\t[ ]\t[ ]\t[ ]\t[ ]\t[ ]', checks:['Deadlines are confirmed rather than inferred.', 'Coverage and authority are distinct.'] },
  { id:'operations-routing', department:'Operations', title:'Route a personal training status notification', inputs:['Studio access and test marker', 'Required status fields', 'Your own notification destination'], prompt:'Design a training flow for messages containing [unique test marker]. Extract work item, current status, owner and next checkpoint using starter variables. Notify only me. Keep missing or conflicting fields visible; add conditional handling only after a basic flow passes tests. Do not update a live queue, reply to senders or make commitments.', example:'TRAINING EXAMPLE. A: Subject TRAINING-STATUS Complete; body Work item T-81, status awaiting supplier, owner Alex, checkpoint 15 December 2026 noon. B: Subject TRAINING-STATUS Missing; body Please chase T-82. C: Subject Lunch; body Meet at noon? Use a private test inbox and notifications to yourself.', template:'Starter / marker:\nField mapping:\nNotification recipient:\nComplete test:\nMissing test:\nUnrelated test:\nRun-history review:\nHow to disable:', checks:['Unrelated messages do not trigger.', 'Notifications go only to the learner.'] },
  { id:'reporting-quality', department:'Reporting', title:'Check a report formula and its denominator', inputs:['Metric definition', 'Relevant cells or table', 'Existing formula and reporting period'], prompt:'Review this reporting calculation against its definition. Show numerator, denominator, formula and cell references. Check blanks, zeros, duplicate records and period consistency. Independently describe one manual calculation. Propose corrections without changing source data, and state what cannot be established.', example:'TRAINING EXAMPLE. Two teams report 18 of 20 and 8 of 10 cases completed within target. The combined measure is total cases within target divided by total eligible completed cases. The proposed formula averages 90% and 80% without weighting. No staffing or causal evidence is provided.', template:'Definition:\nNumerator:\nDenominator:\nExisting formula:\nChecked formula:\nIndependent calculation:\nLimitations:', checks:['The denominator matches the definition.', 'The formula uses summed counts where required.'] },
  { id:'communications-change', department:'Communications', title:'Prepare a coordinated change announcement', inputs:['Approved facts', 'Audience and required action', 'Confirmed launch date and help contact'], prompt:'Use only these approved facts to create an employee email, four manager talking points and a short storyboard. Build a shared fact checklist first. Preserve the launch date, required action and exceptions. Mark creative visual suggestions separately. Leave unanswered details as questions.', example:'TRAINING EXAMPLE. A new service request form launches on 14 December 2026. New requests need a business reason. Existing requests do not need resubmission. Questions go to the Service Desk. The aim is fewer follow-up questions; no percentage saving or completion-time promise is approved.', template:'Shared facts:\nEmployee email:\nManager talking points:\nScene\tNarration\tOn-screen text\tSuggested visual\n1\t[ ]\t[ ]\t[ ]\nOpen questions:', checks:['All formats preserve the same facts.', 'Creative suggestions do not add policy or performance claims.'] },
  { id:'leader-decision', department:'Leadership', title:'Prepare a short decision brief', inputs:['Checked evidence', 'Decision needed', 'Options, constraints and decision owner'], prompt:'Prepare a concise decision brief from these facts. Show decision requested, checked evidence, options, trade-offs, unknowns and next step. Label proposed ownership and dates. Do not invent ROI, approvals or causal explanations. End with three questions a decision owner should resolve.', example:'TRAINING EXAMPLE. A team proposes a two-week request-form pilot. Last week 20 of 50 submissions needed clarification. The proposal changes only the business-reason field and preserves existing approvals. Alex is proposed as pilot owner; sponsor approval and start date are pending. No results or budget saving have been measured.', template:'Decision requested:\nChecked evidence:\nOption A / trade-off:\nOption B / trade-off:\nUnknowns:\nProposed owner / date:\nQuestions to resolve:', checks:['Proposals remain proposals.', 'The decision follows from checked evidence and visible uncertainty.'] },
] satisfies Omit<DepartmentVariant, 'guide'>[]).map(v => [v.id, { ...v, guide:variantGuides[v.id] }]));
